{"tool":"python","code":"from openpyxl.utils import get_column_letter

sheet = wb['Consolidated Tracker']

# Consolidated = Existing Task (rows 3-7, since rows 8-9 are retired) + Additions (rows 3-6)
# Rows 3-7 of answer -> Existing Task rows 3-7
# Rows 8-11 of answer -> Additions rows 3-6
for r in range(3, 12):
    for c in range(1, 6):
        col_letter = get_column_letter(c)
        formula = f"=IF(ROW()<=7,INDIRECT(\"'Existing Task'!{col_letter}\"&ROW()),INDIRECT(\"'Additions'!{col_letter}\"&(ROW()-5)))"
        sheet.cell(row=r, column=c).value = formula

# Verify
for r in range(3, 12):
    row_vals = []
    for c in range(1, 6):
        row_vals.append(sheet.cell(row=r, column=c).value)
    print(r, row_vals)"}

